def clean(df):
    df = df.drop_duplicates().reset_index(drop=True)
    df['body_mass_g'] = df['body_mass_g'].str.replace(',', '').astype(float)
    df.loc[df['body_mass_g'] > 6500, 'body_mass_g'] = df.loc[df['body_mass_g'] > 6500, 'body_mass_g'] / 1000
    df.loc[df['flipper_length_mm'] < 170, 'flipper_length_mm'] = df.loc[df['flipper_length_mm'] < 170, 'flipper_length_mm'].abs()
    df['sex'] = df['sex'].str.lower()
    return df

def answer(df):
    return df.groupby('species')['body_mass_g'].sum().to_dict()
